    void Safe(Action action){if(busy)return;try{action();}catch(Exception ex){MessageBox.Show(this,ex.Message,"操作失败",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
    void ResetOfflineTree(){tree.Nodes.Clear();var root=tree.Nodes.Add("独立离线流程");root.Nodes.Add("1 · BMP 图像源");root.Nodes.Add("2 · 径向找圆");root.Expand();}
    RadialCircleOptions Options()=>extra with {CenterX=(double)fields["cx"].Value,CenterY=(double)fields["cy"].Value,InitialRadius=(double)fields["radius"].Value,SearchHalfWidth=(double)fields["half"].Value,SampleCount=(int)fields["samples"].Value,GradientThreshold=(double)fields["threshold"].Value,Polarity=(EdgePolarity)polarity.SelectedIndex};
    OfflineCirclePlan Plan()=>new("vision-independent.circle-plan.v1",imagePath??throw new InvalidOperationException("请先载入 BMP 图像。"),Options());
    void InvalidateResult(){if(setting)return;last=null;canvas.SetOverlay(Options(),null);resultText.Text="参数已改变；需要重新运行。";}
    void SetOptions(RadialCircleOptions o){var values=new Dictionary<string,decimal>{{"cx",(decimal)o.CenterX},{"cy",(decimal)o.CenterY},{"radius",(decimal)o.InitialRadius},{"half",(decimal)o.SearchHalfWidth},{"samples",o.SampleCount},{"threshold",(decimal)o.GradientThreshold}};foreach(var p in values)if(p.Value<fields[p.Key].Minimum||p.Value>fields[p.Key].Maximum)throw new InvalidDataException("该计划参数超出当前界面可编辑范围。");setting=true;try{extra=o;foreach(var p in values)fields[p.Key].Value=p.Value;polarity.SelectedIndex=(int)o.Polarity;}finally{setting=false;}InvalidateResult();}
    void LoadBmp(string path){using var s=File.OpenRead(path);var image=BmpReader.Read(s);canvas.SetImage(image);imagePath=Path.GetFullPath(path);last=null;status.Text=$"已载入 {Path.GetFileName(path)} · {image.Width} × {image.Height} · 搜索范围由用户指定";}
    public void LoadDemo(){LoadBmp(Path.Combine(AppContext.BaseDirectory,"assets","circle-sample.bmp"));ResetOfflineTree();SetOptions(new(717,507,375,SearchHalfWidth:12));status.Text="官方样例图像 · 独立算法 · 手动外圈搜索范围";}
    void OpenImage(){using var d=new OpenFileDialog(){Filter="BMP 图像|*.bmp"};if(d.ShowDialog(this)!=DialogResult.OK)return;LoadBmp(d.FileName);InvalidateResult();}
    void LoadPlan(){using var d=new OpenFileDialog(){Filter="独立计划|*.vplan.json|JSON|*.json"};if(d.ShowDialog(this)!=DialogResult.OK)return;var p=OfflinePlanStore.Load(d.FileName);using var input=File.OpenRead(p.ImagePath);var image=BmpReader.Read(input);SetOptions(p.Options);canvas.SetImage(image);imagePath=p.ImagePath;last=null;ResetOfflineTree();canvas.SetOverlay(Options(),null);status.Text="独立计划已加载 · 参数由计划显式提供";}
    void SavePlan(){using var d=new SaveFileDialog(){Filter="独立计划|*.vplan.json",FileName="circle.vplan.json"};if(d.ShowDialog(this)==DialogResult.OK){OfflinePlanStore.Save(d.FileName,Plan());status.Text="独立计划已保存；此格式不是原 .sol。";}}
    async Task RunAsync(){if(busy)return;OfflineCirclePlan plan;try{plan=Plan();}catch(Exception ex){MessageBox.Show(this,ex.Message);return;}busy=true;toolbar.Enabled=false;parameterPanel.Enabled=false;status.Text="正在执行独立离线流程…";try{ShowRun(await Task.Run(()=>OfflineCircleExecutor.Run(plan)));}catch(Exception ex){last=null;canvas.SetOverlay(Options(),null);resultText.Text="执行失败："+ex.Message;status.Text="执行失败";}finally{busy=false;toolbar.Enabled=true;parameterPanel.Enabled=true;}}


    void ShowRun(OfflineCircleRunResult run){last=run;canvas.SetImage(run.Image);canvas.SetOverlay(Options(),run.Detection);var d=run.Detection;resultText.Text=d.Circle is CircleFit c?$"检测状态：{d.Status}   边缘点：{d.EdgePoints.Count}\r\n圆心：({c.CenterX:F3}, {c.CenterY:F3})   半径：{c.Radius:F3} px\r\n拟合径向 RMS：{c.RadialRmsError:F4} px   流程用时：{run.ElapsedMilliseconds:F2} ms":"检测状态："+d.Status+"\r\n未得到可用圆；请检查图像、极性及搜索范围。";status.Text="运行完成 · 拟合残差不是相对原算法的误差 · 原厂等价未验证";}
    void ExportResult(){if(last is null)throw new InvalidOperationException("请先运行当前参数。");using var d=new SaveFileDialog(){Filter="结果 JSON|*.json",FileName="circle-result.json"};if(d.ShowDialog(this)!=DialogResult.OK)return;File.WriteAllText(d.FileName,JsonSerializer.Serialize(new {schema="vision-independent.desktop-result.v1",plan=Plan(),last.ImageSha256,last.ElapsedMilliseconds,last.Detection,compatibility="unverified"},new JsonSerializerOptions{WriteIndented=true,Converters={new System.Text.Json.Serialization.JsonStringEnumConverter()}}));status.Text="结果已导出";}
    void OpenVendorSolution(){using var d=new OpenFileDialog(){Filter="VisionMaster 方案|*.sol"};if(d.ShowDialog(this)!=DialogResult.OK)return;using var zip=ZipFile.OpenRead(d.FileName);if(zip.Entries.Count>100000)throw new InvalidDataException("方案条目数超过浏览限制。");var xmls=zip.Entries.Where(e=>e.FullName.Replace('\\','/')=="SolutionFile/VmServer.xml").ToArray();if(xmls.Length!=1||xmls[0].Length>8388608)throw new InvalidDataException("方案配置缺失、重复或过大。");using var stream=xmls[0].Open();using var reader=XmlReader.Create(stream,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=8388608});var root=XDocument.Load(reader).Root??throw new InvalidDataException("缺少方案根节点。");if(root.Name!="Root")throw new InvalidDataException("不支持的方案结构。");var parameters=new Dictionary<string,Dictionary<string,string>>();var frames=zip.Entries.Where(e=>e.FullName.Replace('\\','/')=="SolutionFile/MoudleFrame").ToArray();if(frames.Length==1){var parsed=JsonSerializer.SerializeToElement(ModuleFrame.Inspect(frames[0]));if(parsed.TryGetProperty("records",out var records))foreach(var r in records.EnumerateArray())if(r.TryGetProperty("parameters",out var p)&&p.ValueKind==JsonValueKind.Object&&p.TryGetProperty("items",out var items)){var values=new Dictionary<string,string>();foreach(var item in items.EnumerateArray())values[item.GetProperty("key").GetString()??"?"]=item.GetProperty("text").GetString()??"[未知载荷]";parameters[r.GetProperty("name").GetString()??""]=values;}}
        tree.Nodes.Clear();table.Rows.Clear();var parent=tree.Nodes.Add(Path.GetFileName(d.FileName)+" · 结构浏览");foreach(var m in root.Element("ModulesInfo")?.Element("ModuleBase")?.Elements("Module")??[]){string id=(string?)m.Attribute("Index")??"?",name=(string?)m.Attribute("Name")??"?",label=(string?)m.Attribute("DisplayName")??name;var n=parent.Nodes.Add(id+" · "+label);n.ForeColor=Color.DarkOrange;if(parameters.TryGetValue(id+"-"+name+".mdata",out var values))n.Tag=values;}parent.Expand();status.Text="原 .sol 已打开用于结构浏览；右侧仍为独立离线参数，不执行原方案。";
